const aiItems = $input.all();
const codeItems = $('Validate Rules 1-3').all();

if (aiItems.length !== codeItems.length) {
  throw new Error(
    `Item count mismatch: AI=${aiItems.length}, Code=${codeItems.length}`
  );
}

const reports = [];

for (let i = 0; i < aiItems.length; i++) {
  const source = codeItems[i].json;
  const codeData = source.code_results;
  const raw = aiItems[i].json;

  let aiData = raw.output ?? raw.text ?? raw;

  if (typeof aiData === 'string') {
    const cleaned = aiData
      .replace(/^```(?:json)?\s*/i, '')
      .replace(/\s*```$/, '')
      .trim();

    aiData = JSON.parse(cleaned);
  }

  const results = {
    rule1: codeData.rule1,
    rule2: codeData.rule2,
    rule3: codeData.rule3,
    rule4: aiData.rule4,
    rule5: aiData.rule5
  };

  for (const [rule, value] of Object.entries(results)) {
    if (!['PASS', 'FAIL'].includes(value)) {
      throw new Error(
        `${source.test_case}: Invalid result for ${rule}: ${value}`
      );
    }
  }

  const overall = Object.values(results)
    .every(v => v === 'PASS') ? 'PASS' : 'FAIL';

  const issues = [];

  if (results.rule1 === 'FAIL') {
    issues.push({
      rule: 'rule1',
      variation: 'Overall',
      reason: `Expected 3 variations, found ${codeData.variationCount}`
    });
  }

  if (results.rule2 === 'FAIL') {
    for (const d of codeData.details) {
      if (!d.fieldsComplete) {
        issues.push({
          rule: 'rule2',
          variation: `Variation ${d.variation}`,
          reason: 'Missing Headline, Body, or CTA'
        });
      }
    }
  }

  if (results.rule3 === 'FAIL') {
    for (const d of codeData.details) {
      if (d.wordCount >= 80) {
        issues.push({
          rule: 'rule3',
          variation: `Variation ${d.variation}`,
          reason: `Word count ${d.wordCount} exceeds the allowed limit`
        });
      }
    }
  }

  if (Array.isArray(aiData.issues)) {
    issues.push(...aiData.issues);
  }

  const expected = source.expected;

  const comparison = {};

  for (const rule of Object.keys(results)) {
    comparison[rule] = {
      expected: expected[rule],
      actual: results[rule],
      match: expected[rule] === results[rule]
    };
  }

  const matchedRules = Object.values(comparison)
    .filter(v => v.match).length;

  reports.push({
    json: {
      test_case: source.test_case,
      description: source.description,
      expected,
      actual: results,
      overall,
      evaluation_accuracy: `${matchedRules}/5`,
      test_passed: matchedRules === 5,
      passed_rules: Object.values(results)
        .filter(v => v === 'PASS').length,
      failed_rules: Object.values(results)
        .filter(v => v === 'FAIL').length,
      comparison,
      issues
    },
    pairedItem: { item: i }
  });
}

return reports;

const reports = $input.all().map(item => item.json);

const totalTests = reports.length;

if (totalTests === 0) {
  throw new Error("No test reports received");
}

const passedTests = reports.filter(
  r => r.test_passed === true
);

const failedTests = reports.filter(
  r => r.test_passed !== true
);

let totalRuleChecks = 0;
let matchedRules = 0;

for (const report of reports) {
  const comparisons = Object.values(report.comparison ?? {});

  totalRuleChecks += comparisons.length;

  matchedRules += comparisons.filter(
    c => c.match === true
  ).length;
}

const accuracy = totalRuleChecks > 0
  ? (matchedRules / totalRuleChecks * 100).toFixed(1) + "%"
  : "N/A";

return [{
  json: {
    project: "AI Marketing Agent Evaluation Harness",
    total_tests: totalTests,
    tests_passed: passedTests.length,
    tests_failed: failedTests.length,
    rule_matches: matchedRules,
    total_rule_checks: totalRuleChecks,
    accuracy,
    failed_test_cases: failedTests.map(r => r.test_case),
    test_details: reports.map(r => ({
      test_case: r.test_case,
      overall: r.overall,
      evaluation_accuracy: r.evaluation_accuracy,
      test_passed: r.test_passed
    }))
  }
}];

const items = $input.all();

return items.map(item => {
  const text = String(item.json.test_copy ?? "")
    .replace(/\\n/g, "\n");

  const sections = text
    .split(/(?=Variation\s+\d+\s*:)/i)
    .filter(s => /^Variation\s+\d+\s*:/i.test(s.trim()));

  const rule1 = sections.length === 3 ? "PASS" : "FAIL";

  const details = sections.map((section, index) => {
    const headline = /(?:^|\n)Headline\s*:\s*(.+)/i.exec(section);
    const body = /(?:^|\n)Body\s*:\s*(.+)/i.exec(section);
    const cta = /(?:^|\n)CTA\s*:\s*(.+)/i.exec(section);

    const fieldsComplete = Boolean(
      headline?.[1]?.trim() &&
      body?.[1]?.trim() &&
      cta?.[1]?.trim()
    );

    const content = [headline?.[1], body?.[1], cta?.[1]]
      .filter(Boolean).join(" ");

    const wordCount = content.trim()
      ? content.trim().split(/\s+/).length
      : 0;

    return {
      variation: index + 1,
      fieldsComplete,
      wordCount
    };
  });

  const rule2 = sections.length > 0 &&
    details.every(d => d.fieldsComplete)
    ? "PASS" : "FAIL";

  const rule3 = sections.length > 0 &&
    details.every(d => d.wordCount < 80)
    ? "PASS" : "FAIL";

  return {
    json: {
      ...item.json,
      code_results: {
        rule1,
        rule2,
        rule3,
        variationCount: sections.length,
        details
      }
    }
  };
});

