  } catch (e) {
    return [];
  }
}

const rounds = [
  ...readResults('Recovery Result'),
  ...readResults('Recovery Result - Retry 2'),
  ...readResults('Finalize Retry 3'),
  ...$input.all().map(i => i.json)
];

// 按测试案例去重，保留修复次数最多的结果
const latest = new Map();

for (const r of rounds) {
  if (!r.test_case) continue;

  const old = latest.get(r.test_case);
  if (!old || Number(r.repair_attempt) >= Number(old.repair_attempt)) {
    latest.set(r.test_case, r);
  }
}

const cases = initial.map(r => {
  const repaired = latest.get(r.test_case);

  return {
    test_case: r.test_case,
    final_overall: repaired?.final_overall ?? r.overall,
    repair_attempt: repaired ? Number(repaired.repair_attempt) : 0,
    remaining_issues: repaired?.remaining_issues ?? r.issues ?? []
  };
});

return [{
  json: {
    total_cases: cases.length,
    first_pass: cases.filter(c => c.repair_attempt === 0 && c.final_overall === 'PASS').length,
    repaired_pass: cases.filter(c => c.repair_attempt > 0 && c.final_overall === 'PASS').length,
    final_passed: cases.filter(c => c.final_overall === 'PASS').length,
    final_failed: cases.filter(c => c.final_overall === 'FAIL').length,
    total_repair_attempts: cases.reduce((s, c) => s + c.repair_attempt, 0),
    cases
  }
}];
